export function renderCredentialsRegistry() {
    const eduContainer = document.getElementById('edu-grid-container');
    const profContainer = document.getElementById('prof-grid-container');

    if (!eduContainer && !profContainer) return;

    // Enhancement-only mode: the static HTML cards are the authoritative source
    // (rendered by build_portfolio_html.py from portfolio.json). This function
    // enhances existing cards with registry data (modal layout, gallery URLs)
    // but never creates or duplicates cards.

    // Only enhance cards for items flagged public: true. Items that are not yet
    // surfaced in portfolio.json are kept in the registry for future use but
    // won't match any rendered card.
    const allItems = CREDENTIALS_REGISTRY.filter(item => item.public);

    // Track orphan canonical IDs (registry entries with no rendered card) for
    // easier debugging — printed once to console.
    const matchedCanonicalIds = new Set();

    function enhanceCard(card, item) {
        const modalLayoutJSON = encodeURIComponent(JSON.stringify(item.modal_layout || {}));
        const galleryJSON = encodeURIComponent(JSON.stringify(item.gallery || (item.certificate ? [item.certificate] : [])));
        card.setAttribute('data-gallery', galleryJSON);
        card.setAttribute('data-layout', modalLayoutJSON);
        if (item.canonical_id) matchedCanonicalIds.add(item.canonical_id);
    }

    // Match registry items to existing cards by canonical_id (lowercased) against
    // the data-cert-id attribute. Canonical ID is the single source of identity;
    // the legacy `id` field is preserved for asset filename continuity only.
    const matchById = (container) => {
        if (!container) return;
        const cards = container.querySelectorAll('[data-cert-id]');
        cards.forEach(card => {
            const certId = card.getAttribute('data-cert-id');
            if (!certId) return;
            const matchedItem = allItems.find(item =>
                item.canonical_id &&
                item.canonical_id.toLowerCase() === certId
            );
            if (matchedItem) {
                enhanceCard(card, matchedItem);
            }
        });
    };

    matchById(eduContainer);
    matchById(profContainer);

    // Registry-or-card diagnostic: log any public registry entry that did not
    // match a rendered card. Helps catch drift between the registry and
    // portfolio.json without affecting production behaviour.
    const orphans = allItems
        .filter(item => item.canonical_id && !matchedCanonicalIds.has(item.canonical_id))
        .map(item => item.canonical_id);
    if (orphans.length > 0) {
        console.info('[credentials-registry] Public entries with no rendered card:', orphans);
    }
}
